window.VO = [{"id":"n01","text":"You're looking at someone drowning.","at":0.1,"t0":0.05,"t1":1.535},{"id":"n02","text":"Fifteen seconds.","at":3.77,"t0":1.885,"t1":3.04},{"id":"n03","text":"Find them.","at":6.48,"t0":3.24,"t1":3.93},{"id":"c01","text":"Help!","at":8.66,"t0":4.33,"t1":4.96},{"id":"c02","text":"Hey! Over here!","at":14.84,"t0":7.42,"t1":8.505},{"id":"n04","text":"Halfway.","at":18.14,"t0":9.07,"t1":9.815},{"id":"n05","text":"Last chance.","at":28.44,"t0":14.22,"t1":15.2},{"id":"n06","text":"Time.","at":33.82,"t0":16.91,"t1":17.54},{"id":"n07","text":"It's number nine.","at":36.18,"t0":18.09,"t1":19.115},{"id":"n08","text":"She hasn't made a sound, and she keeps going under.","at":38.73,"t0":19.365,"t1":22.15},{"id":"n09","text":"Did you go for the noise?","at":45.5,"t0":22.75,"t1":24.065},{"id":"n10","text":"The boy was playing, and the man was waving at a boat.","at":48.63,"t0":24.315,"t1":27.21},{"id":"n11","text":"If you found her, you saw what her friends didn't.","at":55.52,"t0":27.76,"t1":30.3},{"id":"n12","text":"They're right there.","at":60.9,"t0":30.45,"t1":31.355},{"id":"c03","text":"Maya?","at":63.61,"t0":31.805,"t1":32.51},{"id":"c04","text":"Maya!","at":66.12,"t0":33.06,"t1":33.74},{"id":"c05","text":"Help!","at":68.18,"t0":34.09,"t1":34.73},{"id":"n13","text":"She can't shout or wave: there's only time to breathe, and both arms are pushing her mouth up.","at":71.16,"t0":35.58,"t1":40.795},{"id":"n14","text":"So don't wait for a shout.","at":82.79,"t0":41.395,"t1":42.75},{"id":"n15","text":"If you're not sure, call for help anyway.","at":85.9,"t0":42.95,"t1":45.105},{"id":"n16","text":"Now look.","at":96.71,"t0":48.355,"t1":49.095}];
